<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\AdminAuditLog;use App\Models\User;use Illuminate\Http\Request;
class AdministratorController extends Controller{public function index(){return response()->json(['administrators'=>User::where('role','super_admin')->get(['id','name','email','photo_url','status','created_at']),'candidates'=>User::whereIn('status',['active','verified'])->where('role','!=','super_admin')->orderBy('name')->get(['id','name','email','graduating_year','photo_url'])]);}public function store(Request $request){$data=$request->validate(['user_id'=>'required|exists:users,id']);$user=User::findOrFail($data['user_id']);abort_unless(in_array($user->status,['active','verified'],true),422,'Only an approved active member can become a Super Admin.');$user->update(['role'=>'super_admin','status'=>'active']);return response()->json(['message'=>'Super Admin access granted.','administrator'=>$user->fresh()]);}public function destroy(Request $request,User $administrator){abort_if($administrator->id===$request->user()->id,422,'You cannot remove your own Super Admin access.');abort_unless($administrator->role==='super_admin',422,'This account is not a Super Admin.');abort_if(User::where('role','super_admin')->count()<=1,422,'The final Super Admin cannot be removed.');$administrator->update(['role'=>'member']);return response()->json(['message'=>'Super Admin access removed.']);}public function audits(){return AdminAuditLog::with('actor:id,name,email')->latest()->paginate(50);}}
